import{_ as a,o as e,a as l,b as r}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/matmul_matrix_diagram.JmTnNB7H.png",s="/ascendc.github.io/assets/matmul_algorithm_diagram.CabJv-Iy.png",c=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"Matmul使用说明","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_usage"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_usage.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_usage.md","outlineHeaders":[{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"},{"level":2,"title":"实现原理","slug":"实现原理","link":"#实现原理"}],"lastUpdated":1788515292000}'),o={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_usage.md"};function d(n,t,b,A,p,f){return e(),l("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>Matmul使用说明</h1><p>Ascend C提供一组Matmul高阶API，方便用户快速实现Matmul矩阵乘法的运算操作。</p><p>Matmul的计算公式为：C = A * B + Bias，其示意图如下。</p><ul><li>A、B为源操作数，A为左矩阵，形状为[M, K]；B为右矩阵，形状为[K, N]。</li><li>C为目的操作数，存放矩阵乘结果的矩阵，形状为[M, N]。</li><li>Bias为矩阵乘偏置，形状为[1, N]。对A*B结果矩阵的每一行都采用该Bias进行偏置。</li></ul><p><strong>图1</strong> Matmul矩阵乘示意图<br><img src="'+i+`" alt title="Matmul矩阵乘示意图"></p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>下文中提及的M轴方向，即为A矩阵纵向；K轴方向，即为A矩阵横向或B矩阵纵向；N轴方向，即为B矩阵横向；尾轴，即为矩阵最后一个维度。</p></div><p>核函数（Kernel）侧实现Matmul矩阵乘运算的步骤概括为：</p><ol><li>创建Matmul对象。</li><li>初始化操作。</li><li>设置左矩阵A、右矩阵B、Bias。</li><li>完成矩阵乘操作。</li><li>结束矩阵乘操作。</li></ol><p>使用Matmul API实现矩阵乘运算的具体步骤如下：</p><ol><li><p>创建Matmul对象。</p><p>创建Matmul对象的示例如下：</p><ul><li>默认为MIX模式（包含矩阵计算和矢量计算），该场景下通常不定义ASCENDC_CUBE_ONLY宏，如果在程序中使用了ASCENDC_CUBE_ONLY宏，则必须使用ASCEND_IS_AIC宏和ASCEND_IS_AIV宏将Cube计算和Vector计算隔离开。</li><li>纯Cube模式（只有矩阵计算）场景下，建议在代码中定义ASCENDC_CUBE_ONLY宏，避免额外的性能开销。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 纯cube模式（只有矩阵计算）场景下，需要设置该代码宏，并且必须在#include &quot;lib/matmul_intf.h&quot;之前设置
// #define ASCENDC_CUBE_ONLY
#include &quot;lib/matmul_intf.h&quot;

typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType;
AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm;
</code></pre></div><p>创建对象时需要传入A、B、C、Bias的参数类型信息，类型信息通过<a href="#table1188045714378">MatmulType</a>来定义，包括：内存逻辑位置、数据格式、数据类型、数据来源的内存逻辑位置。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;
    AscendC::TPosition POSITION, CubeFormat FORMAT, typename TYPE, bool ISTRANS = false,
    LayoutMode LAYOUT = LayoutMode::NONE, bool IBSHARE = false, TPosition SRCPOS = TPosition::GM&gt;
struct MatmulType {
    constexpr static AscendC::TPosition pos = POSITION;
    constexpr static CubeFormat format = FORMAT;
    using T = TYPE;
    constexpr static bool isTrans = ISTRANS;
    constexpr static LayoutMode layout = LAYOUT;
    constexpr static bool ibShare = IBSHARE;
    constexpr static TPosition srcPos = SRCPOS;
};
</code></pre></div><p><strong>表1</strong> MatmulType参数说明</p><p><span id="table1188045714378"></span></p><table><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>POSITION</td><td>内存逻辑位置。<span data-filter="950"><br><br>针对Ascend 950PR/Ascend 950DT：<br> A矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>B矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>Bias可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>C矩阵可设置为TPosition::GM，TPosition::VECIN<br> 注意，A矩阵、B矩阵或Bias矩阵设置为TPosition::VECOUT或TPosition::TSCM时，对应矩阵用于单核计算的数据必须全部在Unified Buffer（UB）或L1 Buffer上，具体样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_vecout">matmul_vecout样例</a>、<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_tscm_src_vecout">自定义数据来源为VECOUT的TSCM输入的Matmul算子样例</a>、<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_tscm">自定义数据来源为GM的TSCM输入的Matmul算子样例</a>。</span><span data-filter="A3"><br><br>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品：<br> A矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>B矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>Bias可设置为TPosition::GM，TPosition::VECOUT<br>C矩阵可设置为TPosition::GM，TPosition::VECIN, TPosition::CO1<br> 注意，C矩阵设置为TPosition::CO1时，C矩阵的数据排布格式仅支持CubeFormat::NZ，C矩阵的数据类型仅支持float、int32_t。</span><span data-filter="910b"><br> <br>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品：<br> A矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>B矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>Bias可设置为TPosition::GM，TPosition::VECOUT<br>C矩阵可设置为TPosition::GM，TPosition::VECIN, TPosition::CO1<br> 注意，C矩阵设置为TPosition::CO1时，C矩阵的数据排布格式仅支持CubeFormat::NZ，C矩阵的数据类型仅支持float、int32_t。</span><span data-filter="310p"><br><br>针对Atlas 推理系列产品AI Core：<br> A矩阵可设置为TPosition::GM，TPosition::VECOUT<br>B矩阵可设置为TPosition::GM，TPosition::VECOUT<br>Bias可设置为TPosition::GM，TPosition::VECOUT<br>C矩阵可设置为TPosition::GM，TPosition::VECIN</span><span data-filter="310b"><br> <br>针对Atlas 200I/500 A2 推理产品：<br> A矩阵可设置为TPosition::GM<br>B矩阵可设置为TPosition::GM<br>Bias可设置为TPosition::GM<br>C矩阵可设置为TPosition::GM</span><span data-filter="x90"><br> <br>针对Kirin X90:<br> A矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM<br>B矩阵可设置为TPosition::GM，TPosition::VECOUT, TPosition::TSCM<br>Bias可设置为TPosition::GM，TPosition::VECOUT<br>C矩阵可设置为TPosition::GM，TPosition::CO1</span><span data-filter="9030"><br> <br>针对Kirin 9030：<br> A矩阵可设置为TPosition::TSCM<br>B矩阵可设置为TPosition::TSCM<br>Bias可设置为TPosition::GM<br>C矩阵可设置为TPosition::GM</span></td></tr><tr><td>FORMAT</td><td>数据的物理排布格式。<span data-filter="950"><br><br>针对Ascend 950PR/Ascend 950DT：<br> A矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::COLUMN_MAJOR，CubeFormat::VECTOR<br>B矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::COLUMN_MAJOR<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::ND_ALIGN，CubeFormat::COLUMN_MAJOR<br> <br>针对Ascend 950PR/Ascend 950DT，请注意：<br> 仅在非MxMatmul场景中，A、B、C矩阵Format支持CubeFormat::COLUMN_MAJOR。当Format为CubeFormat::COLUMN_MAJOR时，对应矩阵仅支持内存逻辑位置为TPosition::GM。<br>输入A矩阵或B矩阵设置为TPosition::TSCM时，对应的Format仅支持CubeFormat::NZ。<br>C矩阵设置为TPosition::VECIN，CubeFormat::ND时，要求尾轴32字节对齐，比如数据类型是half的情况下，N要求是16的倍数。</span><span data-filter="A3"><br> <br>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品：<br> A矩阵可设置为CubeFormat::ND，CubeFormat::NZ, CubeFormat::VECTOR<br>B矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::ND_ALIGN</span><span data-filter="910b"><br> <br>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品：<br> A矩阵可设置为CubeFormat::ND，CubeFormat::NZ, CubeFormat::VECTOR<br>B矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::ND_ALIGN</span><span data-filter="310p"><br> <br>针对Atlas 推理系列产品AI Core：<br> A矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>B矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::ND_ALIGN<br> 注意：针对Atlas 推理系列产品AI Core，C矩阵设置为CubeFormat::ND时，要求尾轴32字节对齐，比如数据类型是half的情况下，N要求是16的倍数。</span><span data-filter="310b"><br> <br>针对Atlas 200I/500 A2 推理产品：<br> A矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>B矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND，CubeFormat::NZ</span><span data-filter="x90"><br> <br>针对Kirin X90:<br> A矩阵可设置为CubeFormat::ND，CubeFormat::NZ, CubeFormat::VECTOR<br>B矩阵可设置为CubeFormat::ND，CubeFormat::NZ<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::ND_ALIGN</span><span data-filter="9030"><br> <br>针对Kirin 9030：<br>A矩阵可设置为CubeFormat::NZ，CubeFormat::VECTOR<br>B矩阵可设置为CubeFormat::NZ<br>Bias可设置为CubeFormat::ND<br>C矩阵可设置为CubeFormat::ND</span><span data-filter="310b"><br><br>注意: 针对Atlas 200I/500 A2 推理产品，C矩阵设置为TPosition::VECIN或者TPosition::TSCM，CubeFormat::ND时，要求尾轴32字节对齐，比如数据类型是half的情况下，N要求是16的倍数；C矩阵设置为TPosition::VECIN或者TPosition::TSCM，CubeFormat::NZ时，N要求是16的倍数。</span><br> <br>关于CubeFormat::NZ格式的A矩阵、B矩阵、C矩阵的对齐约束，请参考<a href="#table98851538118">NZ格式的矩阵对齐要求</a>。</td></tr><tr><td>TYPE</td><td>数据类型。<span data-filter="950"><br><br>针对Ascend 950PR/Ascend 950DT：<br> 1、非MxMatmul场景：<br>A矩阵可设置为half、float、bfloat16_t 、int8_t、fp8_e4m3fn_t、fp8_e5m2_t、hifloat8_t<br>B矩阵可设置为half、float、bfloat16_t 、int8_t、fp8_e4m3fn_t、fp8_e5m2_t、hifloat8_t<br>Bias可设置为half、float、int32_t、bfloat16_t<br>C矩阵可设置为half、float、bfloat16_t、int32_t、int8_t、fp8_e4m3fn_t、hifloat8_t<br> 2、MxMatmul场景：<br>A矩阵可设置为fp8_e4m3fn_t、fp8_e5m2_t、fp4x2_e2m1_t、fp4x2_e1m2_t<br>B矩阵可设置为fp8_e4m3fn_t、fp8_e5m2_t、fp4x2_e2m1_t、fp4x2_e1m2_t<br>Bias可设置为half、float、bfloat16_t<br>C矩阵可设置为half、float、bfloat16_t</span><span data-filter="A3"><br> <br>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品：<br>A矩阵可设置为half、float、bfloat16_t 、int8_t、int4b_t<br>B矩阵可设置为half、float、bfloat16_t 、int8_t、int4b_t<br>Bias可设置为half、float、int32_t<br>C矩阵可设置为half、float、bfloat16_t、int32_t、int8_t</span><span data-filter="910b"><br> <br>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品：<br>A矩阵可设置为half、float、bfloat16_t 、int8_t、int4b_t<br>B矩阵可设置为half、float、bfloat16_t 、int8_t、int4b_t<br>Bias可设置为half、float、int32_t<br>C矩阵可设置为half、float、bfloat16_t、int32_t、int8_t</span><span data-filter="310p"><br><br>针对Atlas 推理系列产品AI Core：<br> A矩阵可设置为half、int8_t<br>B矩阵可设置为half、int8_t<br>Bias可设置为float、int32_t<br>C矩阵可设置为half、float、int8_t、int32_t</span><span data-filter="310b"><br> <br>针对Atlas 200I/500 A2 推理产品：<br> A矩阵可设置为half、float、bfloat16_t 、int8_t<br>B矩阵可设置为half、float、bfloat16_t 、int8_t<br>Bias矩阵可设置为half、float、int32_t<br>C矩阵可设置为half、float、bfloat16_t、int32_t</span><span data-filter="x90"><br> <br>针对Kirin X90:<br> A矩阵可设置为half、int8_t<br>B矩阵可设置为half、int8_t<br>Bias可设置为half、int32_t<br>C矩阵可设置为half、int32_t、int8_t</span><span data-filter="9030"><br> <br>针对Kirin 9030：<br> A矩阵可设置为half<br>B矩阵可设置为half<br>Bias可设置为half<br>C矩阵可设置为half</span><br>注意：除fp8_e4m3fn_t/fp8_e5m2_t两种数据类型、B矩阵为int8_t数据类型外，A矩阵和B矩阵数据类型需要一致，具体数据类型组合关系请参考<a href="#table1996113269499">表2</a>。A矩阵和B矩阵为int4b_t数据类型时，矩阵内轴的数据个数必须为偶数。例如，A矩阵为int4b_t数据类型且不转置时，<a href="../Matmul_Tiling/TCubeTiling_struct.html#p11899125875617">singleCoreK</a>必须是偶数。</td></tr><tr><td>ISTRANS</td><td>是否开启支持矩阵转置的功能。<br> true：开启支持矩阵转置的功能，运行时可以分别通过<a href="SetTensorA.html">SetTensorA</a>和<a href="SetTensorB.html">SetTensorB</a>中的isTransposeA、isTransposeB参数设置A、B矩阵是否转置。若设置A、B矩阵转置，Matmul会认为A矩阵形状为[K, M]，B矩阵形状为[N, K]。<br>false：默认值，不开启支持矩阵转置的功能，通过<a href="SetTensorA.html">SetTensorA</a>和<a href="SetTensorB.html">SetTensorB</a>不能设置A、B矩阵的转置情况。Matmul会认为A矩阵形状为[M, K]，B矩阵形状为[K, N]。<br> <br>注意，由于L1 Buffer上的矩阵数据有分形对齐的约束，A、B矩阵转置和不转置时所需的L1空间可能不相同，在开启支持矩阵转置功能时，必须保证按照<a href="../Matmul_Tiling/TCubeTiling_struct.html">Matmul Tiling参数</a>申请的L1空间不超过L1 Buffer的规格，判断方式为(depthA1*Ceil(baseM/c0Size)<em>baseK + depthB1</em>Ceil(baseN/c0Size)*baseK) * db * sizeof(dtype) &lt; L1Size，db表示L1是否开启double buffer，取值1（不开启double buffer）或2（开启double buffer），其余参数的含义请参考<a href="../Matmul_Tiling/TCubeTiling_struct.html#tcubetiling-struct">表1</a>。<span data-filter="9030"><br> <br>Kirin 9030不支持此参数。</span></td></tr><tr><td>LAYOUT</td><td>表征数据的排布。<br> <br>NONE：默认值，表示不使用BatchMatmul；其他选项表示使用BatchMatmul。<br> <br>NORMAL：BMNK的数据排布格式，具体可参考<a href="IterateBatch.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">IterateBatch</a>中对该数据排布的介绍。<br> <br>BSNGD：原始BSH shape做reshape后的数据排布，具体可参考<a href="IterateBatch.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">IterateBatch</a>中对该数据排布的介绍。<br> <br>SBNGD：原始SBH shape做reshape后的数据排布，具体可参考<a href="IterateBatch.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">IterateBatch</a>中对该数据排布的介绍。<br> <br>BNGS1S2：一般为前两种数据排布进行矩阵乘的输出，S1S2数据连续存放，一个S1S2为一个batch的计算数据，具体可参考<a href="IterateBatch.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">IterateBatch</a>中对该数据排布的介绍。<span data-filter="9030"><br> <br>Kirin 9030不支持此参数。</span></td></tr><tr><td>IBSHARE<span id="p84551411817"></span></td><td>是否开启IBShare（IntraBlock Share）。IBShare的功能是能够复用L1 Buffer上相同的A矩阵或B矩阵数据，复用的矩阵必须在L1 Buffer上全载。A矩阵和B矩阵仅有一个开启IBShare的场景，与<a href="MatmulConfig.html#template-features">IBShare模板</a>配合使用，具体参数设置详见<a href="MatmulConfig.html#matmulconfig-params">表2</a>。<br> <br>注意，A矩阵和B矩阵同时开启IBShare的场景，表示L1 Buffer上的A矩阵和B矩阵同时复用，需要满足：<br> 同一算子中其它Matmul对象的A矩阵和B矩阵也必须同时开启IBShare；<span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，获取矩阵计算结果时，只支持调用<a href="IterateAll.html">IterateAll</a>接口，且只支持输出到GlobalTensor，即计算结果放置于Global Memory的地址。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，获取矩阵计算结果时，只支持调用<a href="IterateAll.html">IterateAll</a>接口，且只支持输出到GlobalTensor，即计算结果放置于Global Memory的地址。</span><span data-filter="950"><br><br>Ascend 950PR/Ascend 950DT，获取矩阵计算结果时，支持输出到GlobalTensor和LocalTensor。输出到LocalTensor，即计算结果放置于Local Memory的场景，默认实现策略与<a href="MatmulPolicy.html">SplitM模板策略</a>相同，且仅支持输出数据类型为float，仅支持<a href="MatmulConfig.html">Norm模板</a>。</span><span data-filter="950"><br> <br>Ascend 950PR/Ascend 950DT支持该参数。</span><span data-filter="A3"><br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。</span><span data-filter="910b"><br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。</span><span data-filter="310p"><br> <br>Atlas 推理系列产品AI Core不支持该参数。</span><span data-filter="310b"><br> <br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br> <br>Kirin X90不支持此参数。</span><span data-filter="9030"><br> <br>Kirin 9030不支持此参数。</span></td></tr><tr data-filter="950"><td>SRC_POSITION</td><td>该参数仅支持Ascend 950PR/Ascend 950DT。<br> <br>A/B矩阵的POSITION参数配置为TPosition::TSCM时，必须要设置TSCM中矩阵数据的来源的内存逻辑位置，默认为TPosition::GM。<br><br>针对Ascend 950PR/Ascend 950DT：<br> A矩阵可设置为TPosition::GM，TPosition::VECOUT<br>B矩阵可设置为TPosition::GM，TPosition::VECOUT</td></tr></tbody></table><div data-filter="950,A3,910b,310p,310b,x90,9030"><p><strong>表2</strong> Matmul输入输出数据类型的支持列表</p><p><span id="table1996113269499"></span></p><table><thead><tr><th>A矩阵</th><th>B矩阵</th><th>Bias</th><th>C矩阵</th><th>支持平台</th></tr></thead><tbody><tr data-filter="950"><td>float</td><td>float</td><td>float/half</td><td>float/half/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="950"><td>half</td><td>half</td><td>float</td><td>float</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 推理系列产品AI Core<br> <br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="950"><td>half</td><td>half</td><td>half</td><td>float/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="950"><td>int8_t</td><td>int8_t</td><td>int32_t</td><td>int32_t/half</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 推理系列产品AI Core<br> <br>Atlas 200I/500 A2 推理产品<br> <br>Kirin X90</td></tr><tr data-filter="A3"><td>int4b_t</td><td>int4b_t</td><td>int32_t</td><td>int32_t/half</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>float</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="950"><td>bfloat16_t</td><td>bfloat16_t</td><td>half</td><td>float/half</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>half</td><td>half</td><td>float</td><td>int8_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>int8_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr data-filter="950"><td>int8_t</td><td>int8_t</td><td>int32_t</td><td>int8_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 推理系列产品AI Core<br> <br>Kirin X90</td></tr><tr data-filter="950"><td>half</td><td>half</td><td>float</td><td>half/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 推理系列产品AI Core<br> <br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="950"><td>half</td><td>half</td><td>half</td><td>half/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 200I/500 A2 推理产品<br> <br>Kirin X90<br> <br>Kirin 9030</td></tr><tr data-filter="950"><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>bfloat16_t/half</td><td>Ascend 950PR/Ascend 950DT<br> <br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br> <br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> <br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="310p"><td>half</td><td>int8_t</td><td>float</td><td>float</td><td>Atlas 推理系列产品AI Core</td></tr><tr data-filter="950"><td>fp8_e4m3fn_t/fp8_e5m2_t</td><td>fp8_e4m3fn_t/fp8_e5m2_t</td><td>float/half/bfloat16_t</td><td>fp8_e4m3fn_t/half/bfloat16_t/float</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr data-filter="950"><td>hifloat8_t</td><td>hifloat8_t</td><td>float/half/bfloat16_t</td><td>hifloat8_t/half/bfloat16_t/float</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr data-filter="950"><td>float</td><td>float</td><td>bfloat16_t</td><td>float/half/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr data-filter="950"><td>bfloat16_t</td><td>bfloat16_t</td><td>bfloat16_t</td><td>float/half/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr data-filter="950"><td>half</td><td>half</td><td>bfloat16_t</td><td>float/half/bfloat16_t</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr data-filter="950"><td>int8_t</td><td>int8_t</td><td>int32_t</td><td>bfloat16_t</td><td>Ascend 950PR/Ascend 950DT</td></tr></tbody></table></div></li><li><p>初始化操作。 <span id="li5878185413338"></span></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化matmul对象，参数含义请参考REGIST_MATMUL_OBJ章节
</code></pre></div></li><li><p>设置左矩阵A、右矩阵B、Bias。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.SetTensorA(gm_a);    // 设置左矩阵A
mm.SetTensorB(gm_b);    // 设置右矩阵B
mm.SetBias(gm_bias);    // 设置Bias
</code></pre></div><div data-filter="310p"><p>Atlas 推理系列产品AI Core上需要额外调用<a href="SetLocalWorkspace.html">SetLocalWorkspace</a>接口设置计算所需的UB空间。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.SetLocalWorkspace(usedUbBufLen);
</code></pre></div></div></li><li><p>完成矩阵乘操作。</p><p>用户可以选择以下三种调用方式之一。</p><ul><li><p>调用<a href="Iterate.html#li135771283591">Iterate</a>完成单次迭代计算，叠加while循环完成单核全量数据的计算。Iterate方式，可以自行控制迭代次数，完成所需数据量的计算，方式比较灵活。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// API接口内部会进行循环结束条件判断处理
while (mm.Iterate()) {
    mm.GetTensorC(gm_c);
}
</code></pre></div></li><li><p>调用<a href="IterateAll.html">IterateAll</a>完成单核上所有数据的计算。IterateAll方式，无需循环迭代，使用比较简单。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.IterateAll(gm_c);
</code></pre></div></li></ul><p><a id="user-managed-co1"></a></p><ul><li><p>用户申请用于存放矩阵乘结果的L0C Buffer（CO1）内存，调用一次或多次<a href="Iterate.html#li4843165185812">Iterate</a>完成单次或多次迭代计算，在需要搬出计算结果时，调用<a href="../../../basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe</a>接口完成L0C Buffer（CO1）上计算结果的搬运，然后释放申请的L0C Buffer（CO1）内存。该方式下，用户可以灵活控制计算和搬运的节奏，根据实际需要，一次计算对应一次结果的搬出，或者将多次计算结果缓存在L0C Buffer（CO1）内存中，再一次性搬出计算结果。</p><p>在此种调用方式下，创建Matmul对象时，必须定义C矩阵的内存逻辑位置为TPosition::CO1、数据排布格式为CubeFormat::NZ、数据类型为float或int32_t。</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT暂不支持该方式。 </li></ul></div><span data-filter="310p"></span></li><li>Atlas 推理系列产品AI Core暂不支持该方式。 <span data-filter="310b"></span></li><li>Atlas 200I/500 A2 推理产品暂不支持该方式。 </li></ul><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 定义C矩阵的类型信息
typedef AscendC::MatmulType&lt;AscendC::TPosition::CO1, CubeFormat::NZ, float&gt; cType;
// 创建Matmul对象
AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm;

// 用户提前申请L0C Buffer（CO1）的内存l0cTensor
TQue&lt;TPosition::CO1, 1&gt; CO1_;
// 128 * 1024为申请的L0C Buffer（CO1）内存大小
GetTPipePtr()-&gt;InitBuffer(CO1_, 1, 128 * 1024);
// L0cT为C矩阵的数据类型。
// A矩阵数据类型是int8_t或int4b_t时，C矩阵的数据类型是int32_t。
// A矩阵数据类型是half、float或bfloat16_t时，C矩阵的数据类型是float。
LocalTensor&lt;L0cT&gt; l0cTensor = CO1_.template AllocTensor&lt;L0cT&gt;();

// 将l0cTensor作为入参传入Iterate，矩阵乘结果输出到用户申请的l0cTensor上
mm.Iterate(false, l0cTensor);

// 调用Fixpipe接口将L0C Buffer（CO1）上的计算结果搬运到GM
FixpipeParamsV220 params;
params.nSize = nSize;
params.mSize = mSize;
params.srcStride = srcStride;
params.dstStride = dstStride;
CO1_.EnQue(l0cTensor);
CO1_.template DeQue&lt;L0cT&gt;();
Fixpipe&lt;cType, L0cT, CFG_ROW_MAJOR&gt;(gm[dstOffset], l0cTensor, params);

// 释放L0C Buffer（CO1）内存
CO1_.FreeTensor(l0cTensor);
</code></pre></div></li><li><p>结束矩阵乘操作。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.End();
</code></pre></div></li></ol><p><span id="table98851538118"></span> CubeFormat::NZ格式的矩阵对齐要求为：</p><ul><li>A矩阵/B矩阵：外轴为16的倍数，内轴为C0_size的倍数。</li></ul><div data-filter="310p,310b"><p>对于如下产品型号：</p><div data-filter="310p"><p>Atlas 推理系列产品AI Core</p></div><div data-filter="310b"><p>Atlas 200I/500 A2 推理产品</p></div><ul><li>C矩阵：外轴为16的倍数，内轴为16的倍数。</li></ul></div><div data-filter="950,A3,910b"><p>对于如下产品型号：</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><ul><li>C矩阵（开启channel_split功能）：外轴为16的倍数，内轴为C0_size的倍数。</li><li>C矩阵（不开启channel_split功能）：外轴为16的倍数，对于float/int32_t类型内轴为16的倍数，对于half/bfloat16_t/int8_t/fp8_e4m3fn_t/fp8_e5m2_t/hifloat8_t类型内轴为C0_size的倍数。</li></ul></div><p>上述参数和概念的补充说明如下：</p><ul><li>float/int32_t数据类型的C0_size为8，half/bfloat16_t数据类型的C0_size为16，int8_t/fp8_e4m3fn_t/fp8_e5m2_t/hifloat8_t数据类型的C0_size为32，int4b_t/fp4x2_e2m1_t/fp4x2_e1m2_t数据类型的C0_size为64。</li><li>channel_split功能通过<a href="MatmulConfig.html#matmulconfig-params">MatmulConfig</a>中的isEnableChannelSplit参数配置，具体内容请参考<a href="MatmulConfig.html#matmulconfig-params">MatmulConfig</a>。</li></ul><h2 id="需要包含的头文件">需要包含的头文件<a class="header-anchor" href="#需要包含的头文件">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/matmul/matmul_intf.h&quot;
</code></pre></div><h2 id="实现原理">实现原理<a class="header-anchor" href="#实现原理">​</a></h2><p>以输入矩阵A (GM, ND, half)、矩阵B(GM, ND, half)，输出矩阵C (GM, ND, float)，无Bias场景为例，其中(GM, ND, half)表示数据存放在GM上，数据格式为ND，数据类型为half，描述Matmul高阶API典型场景的内部算法框图，如下图所示。</p><p><strong>图2</strong> Matmul算法框图<br><img src="`+s+'" alt title="Matmul算法框图"></p><p>计算过程分为如下几步：</p><ol><li>数据从GM搬到L1 Buffer（A1）：DataCopy每次从矩阵A中搬出一个stepM*baseM*stepKa*baseK的矩阵块a1，循环多次完成矩阵A的搬运；数据从GM搬到L1 Buffer（B1）：DataCopy每次从矩阵B中搬出一个stepKb*baseK*stepN*baseN的矩阵块b1，循环多次完成矩阵B的搬运；</li><li>数据从L1 Buffer（A1）搬到L0A Buffer（A2）：LoadData每次从矩阵块a1，搬出一个baseM * baseK的矩阵块a0；数据从L1 Buffer（B1）搬到L0B Buffer（B2），并完成转置：LoadData每次从矩阵块b1，搬出一个baseK * baseN的矩阵块，并将其转置为baseN * baseK的矩阵块b0；</li><li>矩阵乘：每次完成一个矩阵块a0 * b0的计算，得到baseM * baseN的矩阵块co1；</li><li>数据从矩阵块co1搬到矩阵块co2:DataCopy每次搬运一块baseM * baseN的矩阵块co1到singleCoreM * singleCoreN的矩阵块co2中；</li><li>重复2-4步骤，完成矩阵块a1 * b1的计算；</li><li>数据从矩阵块co2搬到矩阵块C：DataCopy每次搬运一块singleCoreM * singleCoreN的矩阵块co2到矩阵块C中；</li><li>重复1-6步骤，完成矩阵A * B = C的计算。</li></ol></article></div>',1)])])}const m=a(o,[["render",d]]);export{c as __pageData,m as default};
